[standards/application/monitoring/STD-APP-MON-002-opentelemetry-observability.md#412-service-configuration]

#### 4.1.2 Service Configuration

```csharp
// Program.cs
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOpenTelemetry()
    .ConfigureResource(resource => resource
        .AddService(
            serviceName: builder.Configuration["Otel:ServiceName"]
                ?? throw new InvalidOperationException("Otel:ServiceName is required"),
            serviceVersion: Assembly.GetExecutingAssembly()
                .GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion
                ?? "unknown")
        .AddAttributes(new Dictionary<string, object>
        {
            ["deployment.environment"] = builder.Environment.EnvironmentName.ToLowerInvariant(),
            ["service.namespace"] = builder.Configuration["Otel:ServiceNamespace"] ?? "default",
        })
        .AddDetector(new ContainerResourceDetector()))
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation(options =>
        {
            // Normalize route templates, exclude health check paths
            options.Filter = ctx => !ctx.Request.Path.StartsWithSegments("/health")
                && !ctx.Request.Path.StartsWithSegments("/ready");
        })
        .AddHttpClientInstrumentation()
        .AddSqlClientInstrumentation(options =>
        {
            options.SetDbStatementForText = false; // Never capture SQL text (may contain PII)
        })
        .AddSource("Gainwell.*") // Register custom ActivitySources
        .AddOtlpExporter())
    .WithMetrics(metrics => metrics
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddRuntimeInstrumentation()
        .AddMeter("Gainwell.*") // Register custom Meters
        .AddOtlpExporter())
    .WithLogging(
        configure: logging => logging
            .AddOtlpExporter(),
        configureOptions: options =>
        {
            options.IncludeScopes = true;
            options.IncludeFormattedMessage = true;
        });
```

