[standards/application/monitoring/STD-APP-MON-002-opentelemetry-observability.md#413-custom-spans-activity-api]

#### 4.1.3 Custom Spans (Activity API)

```csharp
// Define the ActivitySource for the service
public static class Telemetry
{
    public static readonly ActivitySource Source =
        new ActivitySource("Gainwell.Claims.ProcessingService");
}

// Creating a custom span
public async Task<ClaimResult> ProcessClaimAsync(ClaimRequest request)
{
    using var activity = Telemetry.Source.StartActivity(
        "claims.process",
        ActivityKind.Internal);

    // Add business-relevant (non-PII) attributes
    activity?.SetTag("gainwell.domain", "claims");
    activity?.SetTag("gainwell.claim.type", request.ClaimType);
    activity?.SetTag("gainwell.claim.line_count", request.LineItems.Count);

    try
    {
        var result = await _processingEngine.ProcessAsync(request);

        activity?.SetTag("gainwell.claim.outcome", result.Status.ToString());
        activity?.SetStatus(ActivityStatusCode.Ok);
        return result;
    }
    catch (ClaimValidationException ex)
    {
        // Record exception without PII — scrub the exception message if needed
        activity?.SetStatus(ActivityStatusCode.Error, "Claim validation failed");
        activity?.RecordException(ex);
        throw;
    }
}
```

