[standards/application/monitoring/STD-APP-MON-002-opentelemetry-observability.md#423-custom-spans]

#### 4.2.3 Custom Spans

```java
import io.opentelemetry.api.GlobalOpenTelemetry;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.api.trace.Tracer;

@Service
public class ClaimProcessingService {

    private static final Tracer TRACER =
        GlobalOpenTelemetry.getTracer("gainwell.claims.processing", "1.0.0");

    public ClaimResult processClaim(ClaimRequest request) {
        Span span = TRACER.spanBuilder("claims.process")
            .setAttribute("gainwell.domain", "claims")
            .setAttribute("gainwell.claim.type", request.getClaimType())
            .setAttribute("gainwell.claim.line_count", request.getLineItems().size())
            .startSpan();

        try (var scope = span.makeCurrent()) {
            var result = doProcess(request);
            span.setAttribute("gainwell.claim.outcome", result.getStatus().name());
            span.setStatus(StatusCode.OK);
            return result;
        } catch (ClaimValidationException e) {
            span.setStatus(StatusCode.ERROR, "Claim validation failed");
            span.recordException(e);
            throw e;
        } finally {
            span.end();
        }
    }
}
```

