#### 4.4.2 SDK Initialization

```typescript
// instrumentation.ts — must be loaded before all other modules
import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-grpc';
import { OTLPMetricExporter } from '@opentelemetry/exporter-metrics-otlp-grpc';
import { PeriodicExportingMetricReader } from '@opentelemetry/sdk-metrics';
import { Resource } from '@opentelemetry/resources';
import { ATTR_SERVICE_NAME, ATTR_SERVICE_VERSION } from '@opentelemetry/semantic-conventions';

const sdk = new NodeSDK({
  resource: new Resource({
    [ATTR_SERVICE_NAME]: process.env.OTEL_SERVICE_NAME!,
    [ATTR_SERVICE_VERSION]: process.env.SERVICE_VERSION ?? 'unknown',
    'deployment.environment': process.env.DEPLOYMENT_ENVIRONMENT ?? 'local',
    'service.namespace': process.env.SERVICE_NAMESPACE ?? 'default',
  }),
  traceExporter: new OTLPTraceExporter({
    url: process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? 'http://localhost:4317',
  }),
  metricReader: new PeriodicExportingMetricReader({
    exporter: new OTLPMetricExporter({
      url: process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? 'http://localhost:4317',
    }),
  }),
  instrumentations: [
    getNodeAutoInstrumentations({
      '@opentelemetry/instrumentation-http': {
        ignoreIncomingRequestHook: (req) =>
          req.url === '/health' || req.url === '/ready',
      },
    }),
  ],
});

sdk.start();
process.on('SIGTERM', () => sdk.shutdown());
```

```json
// package.json — ensure instrumentation loads before all application modules
{
  "scripts": {
    "start": "node --require ./dist/instrumentation.js dist/server.js"
  }
}
```

> **ESM modules (Node.js 18.19+ / 20+):** For projects using native ES Modules (`"type": "module"` in package.json or `.mjs` files), use `--import` instead of `--require`:
> ```json
> { "scripts": { "start": "node --import ./dist/instrumentation.js dist/server.js" } }
> ```
> Note that `--import` requires the instrumentation file to be loaded as an ES Module. Verify your bundler and Node.js version support before switching from CommonJS `--require`.

